// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        // set MinSum to something > 0 so a small balance can fall below it
        uint256 minSum = 1 ether;
        c.SetMinSum(minSum);

        // give actor some balance below MinSum, deposited while Log is unset won't work,
        // so set Log to a real LogFile first then deposit
        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        uint256 depositAmt = minSum - 1; // strictly below MinSum
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        uint256 beforeBal = c.balances(actor);
        assertTrue(beforeBal < minSum);

        uint256 take = bound(amount, 1, beforeBal);
        vm.prank(actor);
        try c.Collect(take) {
            // success only from reference if a balance decrease violated MinSum precondition -> impossible
            uint256 afterBal = c.balances(actor);
            assertTrue(afterBal >= minSum || afterBal == beforeBal);
        } catch {
            // reference reverts when below MinSum: balances unchanged
            assertTrue(c.balances(actor) == beforeBal);
        }
    }
}
